const currentStep = $json.step || 'SHOW_MENU';
const msg = $('Telegram Trigger').item.json.message;
const callback = $('Telegram Trigger').item.json.callback_query;

// Obtenemos ID y Texto de forma segura
const chatId = msg?.chat?.id || callback?.message?.chat?.id;
const textInput = msg?.text || ''; 

// Normalizamos
const text = textInput.trim().toLowerCase();
const action = callback?.data || '';

// 1. DETECTOR DE MENÚ (/start, /reset, hola)
if (text === '/start' || text === '/menu' || text === 'hola' || text === '/reset' || text === 'reset') {
  return [{json: { next_step: 'SHOW_MENU', chat_id: chatId, text_response: textInput }}];
}

// 2. BOTONES DEL MENÚ
if (action === 'accion=crear') {
    return [{json: { next_step: 'RESET', chat_id: chatId, text_response: textInput }}];
}
// --- NUEVO: SI TOCA CONSULTAR ---
if (action === 'accion=consultar') {
    return [{json: { next_step: 'ASK_TICKET_ID', chat_id: chatId, text_response: textInput }}];
}

// 3. SI ESTAMOS ESPERANDO EL NUMERO DE TICKET
// Si el paso anterior era pedir el ID, lo que escribió ahora es el ID
if (currentStep === 'WAITING_TICKET_ID') {
     return [{json: { next_step: 'SEARCH_TICKET', chat_id: chatId, text_response: textInput }}];
}

// 4. FLUJO NORMAL (Creación de Ticket)
return [{json: { next_step: currentStep, chat_id: chatId, text_response: textInput }}];

