// 1. Obtenemos el Asunto
const subject = $json.subject || '';

// 2. Buscamos el Número de Ticket (Ticket#1234 o #1234)
const ticketMatch = subject.match(/Ticket#(\d+)/i) || subject.match(/#(\d+)/);
const ticketId = ticketMatch ? ticketMatch[1] : 'Pendiente';

// 3. Buscamos el Chat ID Seguro (CID)
// Buscamos el patrón "[CID:12345]" que pusimos en el asunto
const idMatch = subject.match(/\[CID:(\d+)\]/);
const chatId = idMatch ? idMatch[1] : null;

return {
  json: {
    ticket_id: ticketId,
    chat_id: chatId, 
    subject: subject,
    encontrado: !!chatId // True si lo encontró
  }
};
